"""QQ-白模参考：姿态 / 脸模 / 服装 三类参考图库的索引与取图。

设计约束（按需求定死）：

* **所有图片都放在用户目录**，插件目录只放代码::

      <ComfyUI>/user/QQ_ComfyUI_Tools/GuliPoses/pose/img/*.png|jpg|webp
      <ComfyUI>/user/QQ_ComfyUI_Tools/GuliPoses/face/img/...
      <ComfyUI>/user/QQ_ComfyUI_Tools/GuliPoses/garment/img/...

* **不落 index.json**：目录即索引，按「文件数 + 最新 mtime + 总大小」做签名缓存，
  丢图进去刷新页面就能用，不需要重启，也不会有索引和文件不同步的问题。
* **不建 inbox / custom / png 之类的中转目录**：只有一个 ``img/``，
  缩略图由 ``thumbs/`` 按需生成（可随时删掉，会自动重建）。
* 目录可用环境变量 ``QQ_GULI_POSES_DIR`` 整个换盘。
"""

from __future__ import annotations

import os
import re
import threading
import uuid
from pathlib import Path
from typing import Any

IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".webp", ".bmp", ".gif")

#: 三类参考图。``angles`` 为空 = 单图，多出来的角度后缀会被忽略掉。
LIBS: dict[str, dict[str, Any]] = {
    "pose": {
        "name": "姿态",
        "title": "姿态库",
        "angles": {
            "front": "正面",
            "side": "侧面",
            "high": "俯视",
            "low": "仰视",
            "diag": "斜侧",
        },
    },
    "face": {"name": "脸模", "title": "脸模库", "angles": {"front": "正面"}},
    "garment": {"name": "服装", "title": "服装库", "angles": {"front": "正面"}},
}

LIB_KEYS = tuple(LIBS)
UNUSED = "未使用"

THUMB_SIDE = 320
THUMB_QUALITY = 86

_lock = threading.Lock()
_cache: dict[str, dict[str, Any]] = {}


def root() -> Path:
    """用户素材根目录；永远在插件目录外面。"""
    env = (os.environ.get("QQ_GULI_POSES_DIR") or "").strip()
    if env:
        base = Path(env).expanduser()
        return base if base.is_absolute() else (Path.cwd() / base).resolve()
    try:
        import folder_paths

        user_dir = folder_paths.get_user_directory()
    except Exception:
        user_dir = None
    if user_dir:
        return Path(user_dir) / "QQ_ComfyUI_Tools" / "GuliPoses"
    # 没有 ComfyUI 运行时（单元测试）退到临时目录，绝不写插件目录
    import tempfile

    return Path(tempfile.gettempdir()) / "QQ_ComfyUI_Tools" / "GuliPoses"


def lib_dir(lib: str) -> Path:
    return root() / lib


def img_dir(lib: str) -> Path:
    return lib_dir(lib) / "img"


def thumb_dir(lib: str) -> Path:
    return lib_dir(lib) / "thumbs"


def lib_name(lib: str) -> str:
    return str(LIBS.get(lib, {}).get("name") or lib)


def angles_of(lib: str) -> dict[str, str]:
    return dict(LIBS.get(lib, {}).get("angles") or {"front": "正面"})


# ---------------------------------------------------------------------------
# 文件名 → (显示名, 视角)
# ---------------------------------------------------------------------------

_ANGLE_HINTS = {
    "front": "front", "正面": "front",
    "side": "side", "侧面": "side",
    "high": "high", "俯视": "high", "top": "high",
    "low": "low", "仰视": "low",
    "diag": "diag", "斜侧": "diag",
}
_ANGLE_RE = re.compile(r"^(?P<base>.+?)[_\-\s·](?P<token>[a-zA-Z\u4e00-\u9fff]+)$")


def split_angle(stem: str, lib: str) -> tuple[str, str]:
    """``姿势A_side`` → ``("姿势A", "side")``；单图库直接返回 front。"""
    angles = angles_of(lib)
    if len(angles) <= 1:
        return stem, next(iter(angles))
    match = _ANGLE_RE.match(stem)
    if match:
        token = match.group("token").lower()
        key = _ANGLE_HINTS.get(token)
        if key and key in angles:
            base = match.group("base").strip(" _-·")
            if base:
                return base, key
    return stem, "front" if "front" in angles else next(iter(angles))


#: 旧版本的存放位置。只用于一次性搬迁，搬完即删，不再创建。
LEGACY_SUBDIRS = ("custom", "png")


def migrate_legacy(lib: str) -> int:
    """把旧版 ``custom/`` 与 ``png/`` 里的图片搬进 ``img/``。

    老版本把图放在这两个目录；新版本只有 ``img/``。这里做一次无覆盖搬迁，
    搬空后把遗留目录（含 thumbs、meta.json）一并删掉，避免用户升级后图"消失"。
    返回搬迁的文件数。
    """
    base = lib_dir(lib)
    target = img_dir(lib)
    legacy = [base / name for name in LEGACY_SUBDIRS if (base / name).is_dir()]
    if not legacy:
        return 0
    import shutil

    moved = 0
    try:
        target.mkdir(parents=True, exist_ok=True)
    except OSError:
        return 0
    for src in legacy:
        try:
            entries = sorted(src.iterdir())
        except OSError:
            continue
        for entry in entries:
            if not entry.is_file() or entry.suffix.lower() not in IMAGE_EXTS:
                continue
            dest = target / entry.name
            seq = 2
            while dest.exists():
                dest = target / f"{entry.stem} ({seq}){entry.suffix}"
                seq += 1
            try:
                shutil.move(str(entry), str(dest))
                moved += 1
            except OSError:
                pass
        # 清掉遗留目录里的残余（缩略图、meta.json 等）
        for leftover in sorted(src.rglob("*"), key=lambda p: len(p.parts), reverse=True):
            try:
                leftover.unlink() if leftover.is_file() else leftover.rmdir()
            except OSError:
                pass
        try:
            src.rmdir()
        except OSError:
            pass
    if moved:
        invalidate(lib)
    return moved


def _files(lib: str) -> list[tuple[str, int, int]]:
    directory = img_dir(lib)
    found: list[tuple[str, int, int]] = []
    try:
        with os.scandir(directory) as entries:
            for entry in entries:
                if not entry.is_file():
                    continue
                if Path(entry.name).suffix.lower() not in IMAGE_EXTS:
                    continue
                try:
                    stat = entry.stat()
                except OSError:
                    continue
                found.append((entry.name, stat.st_size, int(stat.st_mtime)))
    except OSError:
        return []
    return sorted(found)


def scan(lib: str) -> dict[str, Any]:
    """目录即索引；签名不变就复用缓存。"""
    if lib not in LIBS:
        return {"lib": lib, "name": lib, "items": [], "angles": []}
    try:
        migrate_legacy(lib)
    except Exception:  # 搬迁失败不影响读库
        pass
    files = _files(lib)
    sig = (len(files), max((mtime for _, _, mtime in files), default=0),
           sum(size for _, size, _ in files))
    with _lock:
        cached = _cache.get(lib)
        if cached and cached.get("sig") == sig:
            return cached["data"]

    angles = angles_of(lib)
    groups: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    for name, _size, _mtime in files:
        display, angle = split_angle(Path(name).stem, lib)
        display = display.strip() or Path(name).stem
        key = display
        seq = 2
        while key in groups and angle in groups[key]["angles"]:
            key = f"{display} ({seq})"
            seq += 1
        slot = groups.setdefault(key, {"angles": {}})
        slot["angles"][angle] = {"img": name}
        if key not in order:
            order.append(key)

    items = []
    for key in order:
        slot = groups[key]
        angle_map = {a: slot["angles"][a] for a in angles if a in slot["angles"]}
        if not angle_map:
            angle_map = dict(slot["angles"])
        items.append({
            "id": key,
            "code": key,
            "label": key,
            "cat": lib_name(lib),
            "angles": angle_map,
        })

    data = {
        "lib": lib,
        "name": lib_name(lib),
        "title": str(LIBS[lib].get("title") or lib_name(lib)),
        "angles": [{"key": k, "label": v} for k, v in angles.items()],
        "items": items,
        "unused": UNUSED,
    }
    with _lock:
        _cache[lib] = {"sig": sig, "data": data}
    return data


def labels(lib: str) -> list[str]:
    return [UNUSED] + [item["label"] for item in scan(lib)["items"]]


def find(lib: str, label: str) -> dict[str, Any] | None:
    for item in scan(lib)["items"]:
        if item["label"] == label:
            return item
    return None


def resolve(lib: str, item: dict[str, Any], angle: str | None = None) -> tuple[Path, str]:
    """取某个角度对应的文件；角度不存在就退回该条目的第一个角度。"""
    angles = item.get("angles") or {}
    key = angle if angle in angles else next(iter(angles))
    name = Path(str(angles[key]["img"])).name
    return img_dir(lib) / name, key


# ---------------------------------------------------------------------------
# 缩略图
# ---------------------------------------------------------------------------


def _make_thumb(src: Path, dst: Path) -> None:
    from PIL import Image, ImageOps

    with Image.open(src) as im:
        im = ImageOps.exif_transpose(im)
        if im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info):
            rgba = im.convert("RGBA")
            flat = Image.new("RGB", rgba.size, (255, 255, 255))
            flat.paste(rgba, mask=rgba.split()[-1])
            im = flat
        else:
            im = im.convert("RGB")
        im.thumbnail((THUMB_SIDE, THUMB_SIDE), Image.LANCZOS)
        dst.parent.mkdir(parents=True, exist_ok=True)
        im.save(dst, "JPEG", quality=THUMB_QUALITY, optimize=True)


def ensure_thumb(lib: str, name: str) -> Path | None:
    """缩略图路径；不存在就现生成。任何失败都返回 None，不抛异常。"""
    file_name = Path(str(name or "")).name
    if not file_name or Path(file_name).suffix.lower() not in IMAGE_EXTS:
        return None
    source = img_dir(lib) / file_name
    if not source.is_file():
        return None
    target = thumb_dir(lib) / f"{source.stem}.jpg"
    try:
        if target.is_file() and target.stat().st_mtime_ns >= source.stat().st_mtime_ns:
            return target
    except OSError:
        pass
    tmp = target.with_name(f"{target.name}.{uuid.uuid4().hex[:8]}.tmp")
    try:
        _make_thumb(source, tmp)
        tmp.replace(target)
    except Exception:
        tmp.unlink(missing_ok=True)
        return None
    return target


# ---------------------------------------------------------------------------
# 导入 / 删除
# ---------------------------------------------------------------------------


def _safe_name(filename: str) -> str:
    """只保留文件名主体，去掉路径与可疑字符。"""
    stem = Path(str(filename or "")).name
    stem = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", stem).strip(" ._")
    return stem[:80] or f"image_{uuid.uuid4().hex[:8]}"


def save_upload(lib: str, filename: str, data: bytes, angle: str | None = None) -> str:
    """把上传的图片写进 ``<lib>/img/``；重名自动加序号，绝不覆盖别人的图。"""
    if lib not in LIBS:
        raise ValueError(f"未知图库：{lib}")
    suffix = Path(str(filename or "")).suffix.lower()
    if suffix not in IMAGE_EXTS:
        raise ValueError("只支持 png / jpg / webp / bmp / gif")
    stem = _safe_name(Path(str(filename)).stem)
    if angle and angle in angles_of(lib) and len(angles_of(lib)) > 1:
        stem = f"{stem}_{angle}"
    directory = img_dir(lib)
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / f"{stem}{suffix}"
    seq = 2
    while target.exists():
        target = directory / f"{stem} ({seq}){suffix}"
        seq += 1
    target.write_bytes(data)
    invalidate(lib)
    return target.name


def delete(lib: str, name: str) -> bool:
    file_name = Path(str(name or "")).name
    if lib not in LIBS or not file_name:
        return False
    source = img_dir(lib) / file_name
    if not source.is_file():
        return False
    try:
        source.unlink()
    except OSError:
        return False
    thumb = thumb_dir(lib) / f"{source.stem}.jpg"
    thumb.unlink(missing_ok=True)
    invalidate(lib)
    return True


def invalidate(lib: str) -> None:
    with _lock:
        _cache.pop(lib, None)


# ---------------------------------------------------------------------------
# 取图（节点用）
# ---------------------------------------------------------------------------


def load_pixels(path: Path) -> Any:
    """读成 ComfyUI 的 IMAGE 张量（1, H, W, 3）float32。"""
    import numpy as np
    import torch
    from PIL import Image, ImageOps

    with Image.open(path) as im:
        im = ImageOps.exif_transpose(im)
        if im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info):
            rgba = im.convert("RGBA")
            flat = Image.new("RGB", rgba.size, (255, 255, 255))
            flat.paste(rgba, mask=rgba.split()[-1])
            im = flat
        else:
            im = im.convert("RGB")
        pixels = np.asarray(im, dtype=np.float32) / 255.0
    return torch.from_numpy(pixels)[None, ...]


class LibraryEmpty(RuntimeError):
    """对应图库还没有图。"""


__all__ = [
    "LIBS", "LIB_KEYS", "UNUSED", "LibraryEmpty",
    "root", "lib_dir", "img_dir", "thumb_dir", "lib_name", "angles_of",
    "scan", "labels", "find", "resolve", "ensure_thumb", "save_upload",
    "migrate_legacy", "LEGACY_SUBDIRS",
    "delete", "invalidate", "load_pixels", "split_angle",
]
